-- ============================================================================
--  Gentegre AI — İLAÇ ÜRÜN ADLARINDA YAZIM ONARIMI (865)
--  865_ilac_ad_yazim_onarimi.sql
--
--  Kullanıcı: *"ürün adlarını da tara ve bozuk yazımları düzelt"*.
--  858-864 `etken_madde` alanını onarmıştı; bu dosya aynı taramayı `ad`
--  alanına uygular. 23.002 ürün adı tarandı, 200 satır onarıldı.
--
--  ============ İKİ HATA SINIFI ======================================
--    A) BOŞLUK UNUTULMUŞ (26 kalıp): "İÇEREN AMPUL" → "İÇERENAMPUL",
--       "ENJEKSİYONLUK ÇÖZELTİ" → "ENJEKSİYONLUKÇÖZELTİ",
--       "0,5 ML ENJEKSİYONLUK" → "0,5 MLENJEKSİYONLUK".
--       Tespit: sözcük sözlükte yok ama İKİ katalog sözcüğüne
--       bölünebiliyor (856/857 ilaç sözlüğü).
--       Yapisik yazim METİN DEĞİŞTİREREK değil BOŞLUK EKLENEREK
--       açılır; böylece kaynaktaki büyük/küçük harf ve Türkçe/ASCII
--       yazım aynen korunur ("IVENJEKSİYONLUK" → "IV ENJEKSİYONLUK",
--       "İV" DEĞİL).
--    B) AÇIK HARF HATASI (18 kalıp): İNFÜZON/İNFİZYON → İNFÜZYON,
--       LİYOFLİZE/LİYOZFİLİZE → LİYOFİLİZE, KAPSÜİ/KAPSÜLL → KAPSÜL,
--       ENJEKSİYYONLUK/EENJEKSİYONLUK → ENJEKSİYONLUK, TABLETT → TABLET,
--       İHALASYON → İNHALASYON, SETLSİZ → SETSİZ, "1.V." → "I.V.".
--
--  ============ NEYE DOKUNULMADI (önemli) ============================
--    · İLK SÖZCÜK HİÇ DEĞİŞMİYOR - o MARKA ADIDIR. "FLATON ENTERİK
--      DRAJE" tespitte "FLAKON" sanıldı; kural konuldu, dokunulmadı.
--      Aynı sebeple AMINOSTERIL, ÇİNKOVİT, TORIA korundu.
--    · GEÇERLİ YAZIM VARYANTLARI hata sayılmadı: pediatrik/pediyatrik,
--      pomad/pomat, supozituar/supozituvar, granule, rectal, sterile.
--    · "ENFÜZYON" tescilli adlarda geçen eski yazım (GELOFUSINE
--      ENFÜZYON, TRASYLOL … ENFÜZYON SOLÜSYONU) - bırakıldı.
--    · ASCII yazılmış kayıtlarda düzeltme de ASCII kalır ("COZELETİ" →
--      "COZELTİ"); aksi halde aynı ad yarı Türkçe yarı ASCII olurdu.
--    · BÜYÜK/KÜÇÜK HARF DÜZENİ korunur; Türkçe büyük harf kuralı
--      uygulandı (i → İ, ı → I).
--
--  ============ FATURA / MEDULA ======================================
--  Ürün adı e-Reçete ve MEDULA'ya BARKOD ile gider; ad yalnız ekranda
--  ve belgede görünür. Onarım yazım düzeltmesidir, ürün kimliği
--  değişmez (barkod, ATC, etken madde aynen kalır).
--
--  ============ GÜVENLİK ==============================================
--  Yedek `ilac_ad_yedek_865`; güncelleme id + eski metin eşleştirir,
--  ikinci çalıştırma 0 satır günceller. `ilac` TİTCK'ten aktarılan
--  katalogdur; yeni aktarım eski yazımı geri getirirse dosya yeniden
--  çalıştırılır.
-- ============================================================================
\set ON_ERROR_STOP on
begin;

create table if not exists public.ilac_ad_yedek_865 (
    id           integer primary key,
    ad           character varying(300) not null,
    yedek_tarihi timestamptz not null default now()
);

