update public.ilac i set ad = d.yeni, guncelleme = now()
  from d where i.id = d.id and i.ad = d.eski;

do $$
declare v_yedek integer; v_kalan integer;
begin
    select count(*) into v_yedek from public.ilac_ad_yedek_865;
    select count(*) into v_kalan from public.ilac i
      join public.ilac_ad_yedek_865 y on y.id = i.id where i.ad = y.ad;
    raise notice '865 tamam: yedek % satir, eski yazimi kalan %.', v_yedek, v_kalan;
end $$;

commit;
